    join(dir, "manifest.json"),
    JSON.stringify({ marketAddress: "0x" + "ee".repeat(20), submittedAt: "2026-11-26T10:00:00.000Z", submissionId: "sub-1", idempotencyKey: "k", links: [], files: [], factSignature: "s", asOf: "2026-11-26T11:00:00.000Z" }),
  );
