});

test("mathgen: match_lead_elo — exact enumeration from a tie with an Elo edge", () => {
  const spec: ResearchSpec = {
    marketAddress: "0x" + "23".repeat(20),
    topic: "test-elo",
    miningPath: 2,
    langs: ["en"],
    headline: "h",
    figures: ["f1", "f2"],
    sourceDescriptions: ["s"],
    links: [],
    analysis: {
      kind: "match_lead_elo",
      params: {
        nameA: "A",
        nameB: "B",
        scoreA: 1,
        scoreB: 1,
        eloA: 2780,
        eloB: 2712,
        gamesRemaining: 6,
        drawShare: 0.75,
        scoreSource: "t",
        eloSource: "t",
      },
    },
  };
  const dir = mkdtempSync(join(tmpdir(), "aa-"));
